CREATE OR REPLACE FUNCTION public.claim_ad_reward() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); v_reward integer := 15; v_balance integer; v_last_reward timestamp with time zone; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; INSERT INTO public.credit_wallets (user_id) VALUES (v_user_id) ON CONFLICT (user_id) DO NOTHING; SELECT cw.balance, cw.last_ad_reward_at INTO v_balance, v_last_reward FROM public.credit_wallets AS cw WHERE cw.user_id = v_user_id FOR UPDATE; IF v_last_reward IS NOT NULL AND v_last_reward > now() - interval '10 minutes' THEN RAISE EXCEPTION 'Aguarde alguns minutos antes de ganhar créditos novamente'; END IF; INSERT INTO public.credit_transactions (user_id, amount, transaction_type, description, metadata) VALUES (v_user_id, v_reward, 'ad_reward', 'Recompensa por anúncio assistido', jsonb_build_object('cooldown_minutes', 10)); UPDATE public.credit_wallets AS cw SET balance = cw.balance + v_reward, lifetime_earned = cw.lifetime_earned + v_reward, last_ad_reward_at = now(), updated_at = now() WHERE cw.user_id = v_user_id RETURNING cw.balance INTO v_balance; RETURN jsonb_build_object('awarded', v_reward, 'balance', v_balance); END; $$;